window.VOCAB_HAUSAUFGABEN = [{"id":"01-konjunktiv","no":1,"title":"Konjunktiv","title_en":"Konjunktiv II e frasi con wenn · weil, wegen, deswegen, denn","added":"2026-11-06","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 130","heading":"A  Wenn ich du wäre, würde ich …","heading_en":"Se fossi in te, …","exercises":[{"no":"1","tag":"Wiederholung A2, L8","instruction":"Evas Realität – Evas Wünsche. Ergänzen Sie: *würde – hätte – wäre*.","instruction_en":"La realtà di Eva – i desideri di Eva. Completa con: würde – hätte – wäre.","box":["würde","hätte","wäre"],"example":[{"label":"a","lead":"Eva hat rote Haare.","text":"Sie **hätte** aber gern schwarze Haare."}],"items":[{"label":"b","lead":"Sie ist ein bisschen klein.","text":"Sie ___ aber gern grösser.","gaps":[["wäre"]],"solution":"Sie **wäre** aber gern grösser.","en":"Però le piacerebbe essere più alta.","why":"*grösser sein*: la forma del desiderio di *sein* è **wäre**.","source":"k2"},{"label":"c","lead":"Sie kann nicht Spanisch sprechen.","text":"Sie ___ aber gern gut Spanisch sprechen.","gaps":[["würde"]],"solution":"Sie **würde** aber gern gut Spanisch sprechen.","en":"Però le piacerebbe parlare bene lo spagnolo.","why":"Alla fine c'è un infinito (*sprechen*), quindi il desiderio è **würde** + infinito.","source":"k2"},{"label":"d","lead":"Sie arbeitet in einem Reisebüro.","text":"Sie ___ aber lieber als Reiseführerin arbeiten.","gaps":[["würde"]],"solution":"Sie **würde** aber lieber als Reiseführerin arbeiten.","en":"Però preferirebbe lavorare come guida turistica.","why":"Infinito alla fine (*arbeiten*) → **würde** + infinito. *lieber* = piuttosto, preferibilmente.","source":"k2"},{"label":"e","lead":"Sie hat eine sehr kleine Wohnung.","text":"Sie ___ aber gern eine grosse Wohnung.","gaps":[["hätte"]],"solution":"Sie **hätte** aber gern eine grosse Wohnung.","en":"Però le piacerebbe avere un appartamento grande.","why":"*eine Wohnung haben*: la forma del desiderio di *haben* è **hätte**. Non serve un infinito.","source":"k2"}]},{"no":"2","tag":"A1","instruction":"Was denken die Personen?","instruction_en":"Che cosa pensano le persone?","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Abbina ogni immagine a un'espressione del riquadro.","box":["wäre ich pünktlich im Büro","würde ich jetzt im Garten sitzen","müsste ich nicht bei Regen Velo fahren"],"box_exact":true,"items":[{"label":"1","lead":"Immer muss ich arbeiten!","text":"Wenn ich nicht arbeiten müsste, ___.","gaps":[["würde ich jetzt im Garten sitzen"]],"solution":"Wenn ich nicht arbeiten müsste, **würde ich jetzt im Garten sitzen**.","en":"Se non dovessi lavorare, adesso sarei seduto in giardino.","why":"L'immagine 1 lo mostra mentre lavora, poi mentre sogna su una sdraio. Dopo una frase con *wenn* la principale comincia con il verbo (*würde*).","source":"kond"},{"label":"2","lead":"Warum habe ich kein Auto?","text":"Wenn ich ein Auto hätte, ___.","gaps":[["müsste ich nicht bei Regen Velo fahren"]],"solution":"Wenn ich ein Auto hätte, **müsste ich nicht bei Regen Velo fahren**.","en":"Se avessi una macchina, non dovrei andare in bici sotto la pioggia.","why":"Va in bici sotto la pioggia; una macchina gli risparmierebbe questo. *müsste* è il Konjunktiv II di *müssen*. *Velo* è la parola svizzera per *Fahrrad*.","source":"kond"},{"label":"3","lead":"Der Bus hat schon wieder Verspätung!","text":"Wenn der Bus keine Verspätung hätte, ___.","gaps":[["wäre ich pünktlich im Büro"]],"solution":"Wenn der Bus keine Verspätung hätte, **wäre ich pünktlich im Büro**.","en":"Se il bus non fosse in ritardo, sarei puntuale in ufficio.","why":"Un bus in ritardo la fa arrivare tardi al lavoro. *wäre* è il Konjunktiv II di *sein*.","source":"kond"}]},{"no":"2","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Riscrivi le frasi di a: comincia con la principale, poi la frase con wenn.","example":[{"label":"1","text":"Ich würde **jetzt im Garten sitzen, wenn ich nicht arbeiten müsste.**"}],"items":[{"label":"2","text":"Ich müsste ___.","gaps":[["nicht bei Regen Velo fahren, wenn ich ein Auto hätte","bei Regen nicht Velo fahren, wenn ich ein Auto hätte"]],"solution":"Ich müsste **nicht bei Regen Velo fahren, wenn ich ein Auto hätte.**","en":"Non dovrei andare in bici sotto la pioggia, se avessi una macchina.","why":"Prima la principale, poi la frase con *wenn*. Nella frase con *wenn* il verbo (*hätte*) va alla fine.","source":"wenn"},{"label":"3","text":"Ich wäre ___.","gaps":[["pünktlich im Büro, wenn der Bus keine Verspätung hätte"]],"solution":"Ich wäre **pünktlich im Büro, wenn der Bus keine Verspätung hätte.**","en":"Sarei puntuale in ufficio, se il bus non fosse in ritardo.","why":"Stesso schema: principale, virgola, *wenn* … verbo alla fine (*hätte*).","source":"wenn"}]},{"no":"3","tag":"A1","instruction":"Ordnen Sie zu.","instruction_en":"Completa con le parole del riquadro. Ogni parola si usa una volta; quelle barrate sono usate nell'esempio.","box":["könnte","wäre","hätten","würde","könnte","würde","wäre","würde","würde","müsste"],"box_used":[0,3],"box_exact":true,"example":[{"label":"a","text":"Ich **könnte** viel leichter eine Arbeit finden, wenn ich in der Stadt leben **würde**."}],"items":[{"label":"b","text":"Ich ___ einige Dinge anders machen, wenn ich Chefin in unserer Firma ___.","gaps":[["würde","müsste"],["wäre"]],"solution":"Ich **würde** einige Dinge anders machen, wenn ich Chefin in unserer Firma **wäre**.","en":"Farei alcune cose in modo diverso, se fossi a capo della nostra ditta.","why":"*machen* alla fine → **würde** + infinito. *Chefin sein* → **wäre**, alla fine della frase con *wenn*.","source":"k2"},{"label":"c","text":"Wenn ich Marco ___, ___ ich unbedingt eine Ausbildung machen.","gaps":[["wäre"],["würde","müsste"]],"solution":"Wenn ich Marco **wäre**, **würde** ich unbedingt eine Ausbildung machen.","en":"Se fossi Marco, farei assolutamente una formazione professionale.","why":"*Marco sein* → **wäre** (come *Wenn ich du wäre …*). La principale ha l'infinito *machen* → **würde**.","source":"k2"},{"label":"d","text":"Wenn ich frei entscheiden ___, ___ ich in einer kleinen Firma arbeiten.","gaps":[["könnte"],["würde"]],"solution":"Wenn ich frei entscheiden **könnte**, **würde** ich in einer kleinen Firma arbeiten.","en":"Se potessi decidere liberamente, lavorerei in una piccola ditta.","why":"*frei entscheiden können* → **könnte** alla fine della frase con *wenn*. Principale con *arbeiten* → **würde**.","source":"k2"},{"label":"e","text":"Wenn wir Kinder ___, ___ ich nur halbtags arbeiten.","gaps":[["hätten"],["müsste","würde"]],"solution":"Wenn wir Kinder **hätten**, **müsste** ich nur halbtags arbeiten.","en":"Se avessimo dei figli, dovrei lavorare solo a metà tempo.","why":"*Kinder haben* con *wir* → **hätten**. Il riquadro lascia **müsste** per l'ultimo spazio.","source":"k2","check":"*müsste* e *würde* sono entrambi tedesco corretto in b, c ed e (*Wenn wir Kinder hätten, würde ich nur halbtags arbeiten* va altrettanto bene). Il riquadro dice solo che tre spazi prendono *würde* e uno prende *müsste*; questa soluzione è la ripartizione più probabile. Chiedi al tuo insegnante quale vuole il libro."}]}]},{"page":"AB 132","heading":"B  Ich muss mich beeilen wegen meiner Arbeit.","heading_en":"Devo sbrigarmi a causa del mio lavoro.","exercises":[{"no":"9","tag":"B1","instruction":"Schreiben Sie die Antworten neu mit *weil*.","instruction_en":"Riscrivi le risposte con weil.","example":[{"label":"a","lead":"◆ Warum freust du dich denn so? ○ Wegen meiner guten Note in der Prüfung.","text":"Weil ich eine gute Note in der Prüfung habe."}],"items":[{"label":"b","lead":"◆ Warum ärgerst du dich denn so? ○ Wegen meiner unpünktlichen Freundin.","text":"Weil meine ___.","gaps":[["Freundin unpünktlich ist","Freundin immer unpünktlich ist","Freundin so unpünktlich ist","Freundin zu spät kommt","Freundin immer zu spät kommt"]],"solution":"Weil meine **Freundin unpünktlich ist.**","en":"Perché la mia ragazza non è puntuale.","why":"*wegen* + sostantivo diventa *weil* + una frase con un verbo; il verbo (*ist*) va alla fine.","source":"weil"},{"label":"c","lead":"◆ Warum geht ihr am Samstag nicht wandern? ○ Wegen des schlechten Wetters.","text":"","accept":["Weil das Wetter schlecht ist.","Weil das Wetter so schlecht ist."],"solution":"**Weil das Wetter schlecht ist.**","en":"Perché il tempo è brutto.","why":"*des schlechten Wetters* → *das Wetter ist schlecht*; dopo *weil* il verbo va alla fine.","source":"weil"},{"label":"d","lead":"◆ Warum bist du denn so nervös? ○ Wegen eines wichtigen Termins.","text":"","accept":["Weil ich einen wichtigen Termin habe.","Weil ich einen wichtigen Termin hab."],"solution":"**Weil ich einen wichtigen Termin habe.**","en":"Perché ho un appuntamento importante.","why":"*eines wichtigen Termins* → *ich habe einen wichtigen Termin* (accusativo dopo *haben*); verbo alla fine.","source":"weil"}]},{"no":"10","tag":"B2","instruction":"Ergänzen Sie: *wegen – weshalb – weil – deswegen – denn*.","instruction_en":"Completa con: wegen – weshalb – weil – deswegen – denn. Una parola può essere usata più volte.","box":["wegen","weshalb","weil","deswegen","denn"],"example":[{"label":"a","text":"Ich beginne bald eine Lehre als Hotelfachfrau. **Deswegen** lerne ich in den Ferien Deutsch."}],"items":[{"label":"b","text":"Ich verstehe ihn ___ seiner Aussprache nur schlecht.","gaps":[["wegen"]],"solution":"Ich verstehe ihn **wegen** seiner Aussprache nur schlecht.","en":"A causa della sua pronuncia lo capisco solo male.","why":"Segue un sostantivo (*seiner Aussprache*, genitivo), non una frase → la preposizione **wegen**.","source":"wegen"},{"label":"c","text":"Irgendwann möchte ich gern nach Italien reisen, ___ ich möchte gern das Meer sehen.","gaps":[["denn"]],"solution":"Irgendwann möchte ich gern nach Italien reisen, **denn** ich möchte gern das Meer sehen.","en":"Un giorno vorrei viaggiare in Italia, perché vorrei vedere il mare.","why":"Dopo lo spazio il verbo resta in 2a posizione (*ich möchte*) → **denn**. Con *weil* andrebbe alla fine.","source":"denn"},{"label":"d","text":"Ich muss mein Hörverstehen verbessern, ___ schaue ich viele Filme an.","gaps":[["deswegen","deshalb"]],"solution":"Ich muss mein Hörverstehen verbessern, **deswegen** schaue ich viele Filme an.","en":"Devo migliorare la comprensione orale, per questo guardo molti film.","why":"La seconda parte è la conseguenza, e il verbo viene subito dopo lo spazio (*schaue ich*) → **deswegen**.","source":"deswegen"},{"label":"e","text":"Meine Kinder haben schnell Deutsch gelernt, ___ sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","gaps":[["weil"]],"solution":"Meine Kinder haben schnell Deutsch gelernt, **weil** sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","en":"I miei figli hanno imparato il tedesco in fretta, perché all'asilo stanno sempre con bambini svizzeri.","why":"Il verbo è alla fine (*zusammen sind*) → **weil**.","source":"weil"},{"label":"f","text":"___ schreibst du die Wörter auf Kärtchen?","gaps":[["Weshalb"]],"solution":"**Weshalb** schreibst du die Wörter auf Kärtchen?","en":"Perché scrivi le parole su dei bigliettini?","why":"Serve una parola interrogativa: **Weshalb** significa *warum* (perché)."},{"label":"g","text":"Meine Schwester spricht schon fast fliessend Deutsch, ___ kann sie mir beim Deutschlernen helfen.","gaps":[["deswegen","deshalb"]],"solution":"Meine Schwester spricht schon fast fliessend Deutsch, **deswegen** kann sie mir beim Deutschlernen helfen.","en":"Mia sorella parla già il tedesco quasi correntemente, per questo può aiutarmi a impararlo.","why":"Conseguenza, e il verbo viene subito dopo lo spazio (*kann sie*) → **deswegen**.","source":"deswegen"}]},{"no":"11","marker":"◇","tag":"B2","instruction":"Im Sprachkurs. Ergänzen Sie: *weil – wegen – deswegen*.","instruction_en":"Al corso di lingua. Completa con: weil – wegen – deswegen.","box":["weil","wegen","deswegen"],"example":[{"label":"a","text":"Ich möchte einen Sprachkurs machen, **deswegen** bin ich jetzt hier."}],"items":[{"label":"b","text":"Die letzte Übung konnte ich nicht machen, ___ ich sie nicht verstanden habe.","gaps":[["weil"]],"solution":"Die letzte Übung konnte ich nicht machen, **weil** ich sie nicht verstanden habe.","en":"Non sono riuscito a fare l'ultimo esercizio, perché non l'avevo capito.","why":"Il verbo è alla fine (*verstanden habe*) → **weil**.","source":"weil"},{"label":"c","text":"Bei der Anmeldung war niemand da. ___ bin ich wieder nach Hause gegangen.","gaps":[["Deswegen","Deshalb"]],"solution":"Bei der Anmeldung war niemand da. **Deswegen** bin ich wieder nach Hause gegangen.","en":"All'iscrizione non c'era nessuno. Per questo sono tornato a casa.","why":"Una nuova frase che dà la conseguenza, con il verbo subito dopo lo spazio (*bin ich*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Ich musste ___ meiner guten Noten zum Kursbeginn keinen Test machen.","gaps":[["wegen"]],"solution":"Ich musste **wegen** meiner guten Noten zum Kursbeginn keinen Test machen.","en":"Grazie ai miei bei voti non ho dovuto fare un test all'inizio del corso.","why":"Segue un gruppo nominale (*meiner guten Noten*, genitivo plurale) → **wegen**.","source":"wegen"},{"label":"e","text":"Es gibt einen extra Sprachkurs, ___ sich sehr viele Teilnehmer angemeldet haben.","gaps":[["weil"]],"solution":"Es gibt einen extra Sprachkurs, **weil** sich sehr viele Teilnehmer angemeldet haben.","en":"C'è un corso di lingua in più, perché si sono iscritti moltissimi partecipanti.","why":"Il verbo è alla fine (*angemeldet haben*) → **weil**.","source":"weil"},{"label":"f","text":"Ich konnte gestern ___ meiner Zahnschmerzen leider nicht in den Kurs kommen.","gaps":[["wegen"]],"solution":"Ich konnte gestern **wegen** meiner Zahnschmerzen leider nicht in den Kurs kommen.","en":"Ieri purtroppo non sono potuto venire al corso a causa del mal di denti.","why":"Segue un gruppo nominale (*meiner Zahnschmerzen*, genitivo plurale) → **wegen**.","source":"wegen"}]},{"no":"12","marker":"◆","tag":"B2","instruction":"Wer findet die besten Ausreden? Wählen Sie eine Situation und schreiben Sie.","instruction_en":"Chi trova le scuse migliori? Scegli una situazione e scrivi. Le risposte modello sono solo una possibilità ciascuna.","phrases":["Ich habe/bin … Deswegen …","Leider habe/bin ich …, weil/denn …","Wegen …"],"example":[{"label":"a","text":"Leider konnte ich die Küche nicht aufräumen, …"}],"items":[{"label":"a","lead":"Ihre Frau hat Sie gebeten, die Küche aufzuräumen. Sie haben aber lieber einen Film angeschaut.","text":"","open":true,"solution":"Leider konnte ich die Küche nicht aufräumen, **weil** ich plötzlich starke Rückenschmerzen hatte. Ich musste mich hinlegen. **Deswegen** habe ich einen Film angeschaut.","en":"Purtroppo non ho potuto riordinare la cucina, perché all'improvviso ho avuto un forte mal di schiena. Ho dovuto sdraiarmi. Per questo ho guardato un film.","why":"Usa *weil* (verbo alla fine: *hatte*) e *Deswegen* (verbo subito dopo: *habe ich*).","source":"weil"},{"label":"b","lead":"Sie sind nicht an die Abschlussprüfung von Ihrem Sprachkurs gegangen.","text":"","open":true,"solution":"**Wegen** einer Grippe bin ich nicht an die Abschlussprüfung gegangen. Ich hatte hohes Fieber, **deswegen** bin ich im Bett geblieben.","en":"A causa dell'influenza non sono andato all'esame finale. Avevo la febbre alta, per questo sono rimasto a letto.","why":"Usa *wegen* + genitivo (*einer Grippe*) e *deswegen* + verbo (*bin ich*).","source":"wegen"},{"label":"c","lead":"Sie kommen zum Essen am 80. Geburtstag Ihrer Grossmutter zwei Stunden zu spät.","text":"","open":true,"solution":"Es tut mir so leid! Leider bin ich zu spät gekommen, **denn** auf der Autobahn war ein Unfall. **Wegen** des Staus habe ich zwei Stunden verloren.","en":"Mi dispiace tanto! Purtroppo sono arrivato tardi, perché in autostrada c'era stato un incidente. A causa della coda ho perso due ore.","why":"*denn* lascia il verbo in 2a posizione (*war*). *wegen des Staus*: genitivo di *der Stau*.","source":"denn"}]}]}],"sources":[{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (frasi ipotetiche, comprese quelle irreali con il Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"wenn","title":"dizionario dei connettivi di grammis: wenn (subordinante, verbo alla fine)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"},{"id":"weil","title":"dizionario dei connettivi di grammis: weil (subordinante, verbo alla fine)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"dizionario dei connettivi di grammis: denn (causale, il verbo resta in 2a posizione)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"dizionario dei connettivi di grammis: deswegen (conseguenza; sta prima del verbo o in mezzo alla frase)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen con il genitivo)","url":"https://grammis.ids-mannheim.de/fragen/67"}]}];
